"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[99999],{46586:e=>{e.exports=JSON.parse('{"functions":[{"name":"Init","desc":"Initialises all audio subsystems and must be called exactly once, from\\nthe client bootstrap (`SoundController.client.luau`).\\n\\nCalling `Init` more than once is a no-op.  On first call it:\\n- Ensures the volume buses, listener, and positional SFX pool exist.\\n- Starts measuring every known asset\'s loudness in the background.\\n- Connects the server-replication listener for positional sounds.\\n- Warms per-asset positional pools so the first `PlaySFXAt` is instant.\\n- Auto-starts any ambience beds listed in `SoundConfig.Ambience.Autostart`.","params":[],"returns":[],"function_type":"static","source":{"line":53,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlaySFX","desc":"Plays a non-positional (2D) one-shot sound effect by its config name.\\n\\nThe sound is looked up in `SoundConfig.Sfx`, played through the\\nappropriate bus, then destroyed automatically when it ends.\\nSubject to per-asset debounce if configured.","params":[{"name":"name","desc":"Key in `SoundConfig.Sfx` (e.g. `\\"refuel_success\\"`).","lua_type":"string"},{"name":"opts","desc":"Optional overrides for volume, pitch, debounce, and replication.","lua_type":"PlayOptions?"}],"returns":[],"function_type":"static","source":{"line":108,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlaySFXAt","desc":"Plays a positional (3D) one-shot sound effect anchored at `position`.\\n\\nUses the pooled `AudioPlayer` / `AudioEmitter` voices for instant playback.  If\\n`opts.Replicate` (or the config `Replicate` flag) is `true`, a packet\\nis fired to replicate the sound on all other clients.","params":[{"name":"name","desc":"Key in `SoundConfig.Sfx`.","lua_type":"string"},{"name":"position","desc":"World-space origin of the sound.","lua_type":"Vector3"},{"name":"opts","desc":"Optional overrides for volume, pitch, debounce, and replication.","lua_type":"PlayOptions?"}],"returns":[],"function_type":"static","source":{"line":123,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlayLooped","desc":"Starts a looping sound and returns a `LoopHandle` for runtime control.\\n\\nThe handle exposes `:FadeTo(volume, duration?)`, `:Stop(fadeDuration?)`,\\nand `:Destroy()`.  Returns `nil` if the name is unknown or has no asset\\nid.  Pass `opts.FadeIn` to ramp the volume up from zero on start.","params":[{"name":"name","desc":"Key in `SoundConfig.Sfx`.","lua_type":"string"},{"name":"opts","desc":"Optional overrides; `FadeIn` fades from 0 to target volume.","lua_type":"PlayOptions?"}],"returns":[{"desc":"Control handle, or `nil` if the asset is not configured.","lua_type":"LoopHandle?"}],"function_type":"static","source":{"line":138,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlayMusic","desc":"Starts the music system, optionally targeting a named playlist.\\n\\nIf `playlistName` is omitted the default playlist defined in\\n`SoundConfig` is used.  Calling while music is already playing\\nperforms a crossfade into the new playlist.  Track ids come from\\n`ReplicatedStorage.BGMs`: per-biome playlists read the folder for\\n`biome`, the others read the shared folder.","params":[{"name":"playlistName","desc":"Name of a playlist in `SoundConfig`; omit for the default.","lua_type":"string?"},{"name":"biome","desc":"`CurrentBiome` id; only per-biome playlists use it.","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":157,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"SkipMusic","desc":"Skips the currently playing music track and advances to the next one\\nin the active playlist.","params":[],"returns":[],"function_type":"static","source":{"line":166,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"StopMusic","desc":"Stops the currently playing music track.","params":[{"name":"fade","desc":"Fade-out duration in seconds; stops immediately when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":175,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"SetAmbience","desc":"Replaces the active ambience bed set with exactly the supplied list.\\n\\nBeds currently playing that are absent from `names` are faded out;\\nbeds in `names` that are not yet playing are faded in.","params":[{"name":"names","desc":"Array of ambience-bed config names to make active.","lua_type":"{string}"},{"name":"fade","desc":"Crossfade duration in seconds; snaps instantly when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":191,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"AddAmbience","desc":"Fades in a single ambience bed without affecting others that are\\nalready playing.","params":[{"name":"name","desc":"Ambience-bed config name to add.","lua_type":"string"},{"name":"fade","desc":"Fade-in duration in seconds; starts at full volume when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":202,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"RemoveAmbience","desc":"Fades out and stops a single ambience bed without affecting others.","params":[{"name":"name","desc":"Ambience-bed config name to remove.","lua_type":"string"},{"name":"fade","desc":"Fade-out duration in seconds; stops immediately when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":212,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"StopAmbience","desc":"Fades out and stops all currently playing ambience beds.","params":[{"name":"fade","desc":"Fade-out duration in seconds; stops all immediately when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":221,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"SetVolume","desc":"Sets the volume of a named bus. Never touches the normalizer: raising a\\nbus raises every sound on it by exactly that factor.\\n\\nValid group names match the keys defined in `SoundConfig.GroupVolumes`:\\n`\\"Master\\"`, `\\"SFX\\"`, `\\"BGM\\"`, `\\"Ambience\\"`, `\\"UI\\"`.","params":[{"name":"group","desc":"Bus name.","lua_type":"string"},{"name":"volume","desc":"Target volume, `0..9` (higher values cap at 9).","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":238,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"GetVolume","desc":"Returns the value last passed to `SetVolume` for a named bus.","params":[{"name":"group","desc":"Bus name.","lua_type":"string"}],"returns":[{"desc":"The player\'s volume value.","lua_type":"number"}],"function_type":"static","source":{"line":250,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}}],"properties":[],"types":[],"name":"SoundManager","desc":"Single entry point for all client audio (SFX, BGM, ambience).\\nCall `Init` once from `SoundController.client.luau`; all other client\\nscripts and tools call the `Play*`, `Music`, `Ambience`, and volume\\nmethods.  Never create ad-hoc `Sound` or `AudioPlayer` instances \u2014 let\\nSoundManager manage pooling, buses, normalization, and replication.\\nBuilt on the advanced audio API (`AudioPlayer` \u2192 `AudioFader` buses \u2192\\n`AudioLimiter` \u2192 `AudioDeviceOutput`). Every asset is loudness-normalized\\nautomatically (`SoundConfig.Normalize`); config `Volume` values are a mix\\non top (default 1.0). Asset ids, pitch ranges, and playlist definitions\\nlive in `Configs/SoundConfig`.","realm":["Client"],"source":{"line":21,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}}')}}]);